/* ==UserStyle==
@name           Rosé Pine for Bluesky
@description    Soho vibes for Bluesky
@version        1.0.0
@license        MIT
@author         Julia Mertz (https://github.com/juliamertz)
@namespace      https://github.com/rose-pine/
@homepageURL    https://github.com/rose-pine/userstyles
@updateURL      https://github.com/rose-pine/userstyles/raw/main/styles/bluesky/rose-pine.user.less
@preprocessor   less

@var select lightVariant "Light Variant" ["main:Rosé Pine", "moon:Rosé Pine Moon", "dawn:Rosé Pine Dawn*"]
@var select darkVariant "Dark Variant" ["main:Rosé Pine*", "moon:Rosé Pine Moon", "dawn:Rosé Pine Dawn"]
@var select accentColor "Accent" ["love:Love*", "gold:Gold", "rose:Rose", "pine:Pine", "foam:Foam", "iris:Iris"]
==/UserStyle== */

@-moz-document domain("bsky.app") {
	@media (prefers-color-scheme: light) {
		html.colorMode--system {
			#rose-pine(@lightVariant, @accentColor);
		}
	}
	@media (prefers-color-scheme: dark) {
		html.colorMode--system {
			#rose-pine(@darkVariant, @accentColor);
		}
	}
	html.theme--light {
		#rose-pine(@lightVariant, @accentColor);
	}
	html.theme--dim,
	html.theme--dark {
		#rose-pine(@darkVariant, @accentColor);
	}
	#rose-pine(@lookup, @accent) {
		@base: @rose-pine[@@lookup][@base];
		@surface: @rose-pine[@@lookup][@surface];
		@overlay: @rose-pine[@@lookup][@overlay];
		@muted: @rose-pine[@@lookup][@muted];
		@subtle: @rose-pine[@@lookup][@subtle];
		@text: @rose-pine[@@lookup][@text];
		@love: @rose-pine[@@lookup][@love];
		@gold: @rose-pine[@@lookup][@gold];
		@rose: @rose-pine[@@lookup][@rose];
		@pine: @rose-pine[@@lookup][@pine];
		@foam: @rose-pine[@@lookup][@foam];
		@iris: @rose-pine[@@lookup][@iris];
		@highlightLow: @rose-pine[@@lookup][@highlightLow];
		@highlightMed: @rose-pine[@@lookup][@highlightMed];
		@highlightHigh: @rose-pine[@@lookup][@highlightHigh];
		@accent-color: @rose-pine[@@lookup][@@accent];
		color-scheme: if(@lookup = dawn, light, dark);
		// fix general site background - this applies to the <html> element
		background-color: @surface;
		::selection {
			background-color: fade(@accent-color, 30%);
		}
		input,
		textarea {
			&::placeholder {
				color: @subtle !important;
			}
		}
		--text: @text;
		--background: @surface;
		--backgroundLight: @surface;
		/* generic text */
		[style*="color: rgb(255, 255, 255)"],
		[style*="color: rgb(241, 243, 245)"] //,
		/* [style*="color: rgb(11, 15, 20)"] this breas on dark */ {
			color: @text !important;
		}
		/* some background color of follow button */
		[style*="background-color: rgb(241, 243, 245)"] {
			background-color: @text !important;
		}
		[style*="color: rgb(11, 15, 20)"] {
			color: if(@lookup = dawn, @text, @base) !important;
		}
		/* secondary text */
		[style*="rgb(169, 183, 197)"],
		[style*="rgb(140, 158, 178)"],
		[style*="rgb(84, 110, 138)"],
		[style*="rgb(66, 87, 108)"] {
			color: @subtle !important;
		}
		// white bottons on the theme/color mode selection in settings
		div[style*="background-color: rgb(197, 207, 217)"],
		// dark
		div[style*="background-color: rgb(201, 210, 219)"],
		// dim
		div[style*="background-color: rgb(46, 63, 81)"] // light

		{
			background-color: @text !important;
			> div {
				color: @base !important;
			}
		}
		/* generic blue inline (e.g. link text, etc) */
		[style*="color: rgb(16, 131, 254)"],
		// dark
		[style*="color: rgb(32, 139, 254)"] // dim

		{
			color: @accent-color !important;
		}
		/* generic blue inline underline (links) */
		[style*="text-decoration-color: rgb(16, 131, 254)"],
		// dark
		[style*="text-decoration-color: rgb(32, 139, 254)"] // dim

		{
			text-decoration-color: @accent-color !important;
		}
		/* generic blue inline bg color (e.g. notification count) */
		[style*="background-color: rgb(16, 131, 254)"],
		// dark
		[style*="background-color: rgb(32, 139, 254)"] // dim

		{
			background-color: @accent-color !important;
			/* notification count contrast fix, also chat message contrast fix (> div) */
			&[style*="color: rgb(241, 243, 245)"],
			 > div {
				color: @base !important;
			}
		}
		/* sending/pending/failed direct message */
		[style*="background-color: rgb(1, 64, 132)"] {
			background-color: fadeout(@accent-color, 70%) !important;
		}
		/* blue svg inline */
		[stroke="hsl(211, 99%, 53%)"],
		[stroke="#0085ff"] {
			stroke: @accent-color;
		}
		[fill="hsl(211, 99%, 53%)"],
		[fill="hsl(211, 99%, 56%)"],
		[fill="#0085ff"] {
			fill: @accent-color;
		}
		/* a lot of blue things (buttons etc) */
		.r-wzwllv,
		div[style*="background-color: rgb(0, 133, 255)"] {
			background-color: @accent-color !important;
		}
		/* subscribe to labeler button */
		button[data-testid="toggleSubscribeBtn"] {
			> div {
				background-color: @iris !important;
				> div {
					color: @base !important;
				}
			}
		}
		/* direct message "failed to send" text */
		span[style*="color: rgb(205, 10, 55)"] {
			color: @love !important;
		}
		/* red button text (delete my account) */
		[style*="color: rgb(251, 162, 178)"] {
			color: @love !important;
		}
		/* red button (delete, etc) */
		button[style*="background-color: rgb(244, 11, 66)"],
		// dark, light (same color)
		button[style*="background-color: rgb(246, 60, 103)"],
		// dark (hover)
		button[style*="background-color: rgb(245, 41, 88)"],
		// dim
		button[style*="background-color: rgb(247, 84, 122)"],
		// dim (hover)
		button[style*="background-color: rgb(205, 10, 55)"] // light (hover)

		{
			background-color: @love !important;
			&:hover {
				background-color: fade(@love, 70%) !important;
			}
			// text color
			> div {
				color: @base !important;
			}
		}
		/* delete account button */
		[style^="background-color: rgb(79, 3, 20)"] {
			background-color: @love !important;
		}
		path[fill="#fba2b2"] {
			fill: @base;
		}
		/* generic background color */
		[style*="background-color: rgb(255, 255, 255)"],
		[style*="background-color: rgb(0, 0, 0)"],
		[style*="background-color: rgb(22, 30, 39)"] {
			background-color: @surface !important;
			& when (@lookup = dawn) {
				/* fix button colors in dawn */
				[style*="background-color: rgb(0, 0, 0)"] {
					background-color: @text !important;
				}
			}
		}
		/* secondary background color */
		[style*="background-color: rgb(20, 25, 31)"],
		/* dark? */ [style*="background-color: rgb(20, 27, 35)"],
		/* dark */ [style*="background-color: rgb(30, 41, 54)"] /* dim */ {
			background-color: @surface !important;
		}
		/* secondary background color when active (e.g. search bar, hovering some buttons like cancel) */
		[style*="background-color: rgb(28, 39, 50)"],
		// dark
		[style*="background-color: rgb(38, 53, 68)"] // dim

		{
			background-color: @base !important;
		}
		/* some sort of tertiary background color with a slight accent */
		[style*="background-color: rgb(0, 25, 51)"] {
			background-color: fadeout(@accent-color, 70%) !important;
		}
		/* loading circle */
		circle[style^="stroke: rgb(25, 118, 210)"] {
			stroke: @accent-color !important;
		}
		/* wide site: new post button (w text) */
		button[style*="background-color: rgb(16, 131, 254)"],
		// dark
		button[style*="background-color: rgb(52, 150, 254)"],
		// dark (hover)
		button[style*="background-color: rgb(32, 139, 254)"],
		// dim
		button[style*="background-color: rgb(76, 162, 254)"] // dim (hover)

		{
			background-color: @accent-color !important;
			&:hover {
				background-color: fade(@accent-color, 70%) !important;
			}
			> div {
				color: @base !important;
			}
			svg > path {
				fill: @base !important;
			}
		}
		/* borders */
		.css-175oi2r {
			border-color: @overlay !important;
		}
		/* fix selected tab bottom border issue caused by selector above */
		.css-175oi2r[style*="border-bottom-color: rgb(16, 131, 254)"] {
			border-bottom-color: @accent-color !important;
		}
		/* fixes the bottom border on tabs (timeline) having a darker color */
		.r-oucylx {
			border-bottom-color: @surface !important;
		}
		/* current selected tab (acc page) !! KEEP THIS BELOW ABOVE DEFINITION !! */
		[style*="border-color: rgb(255, 255, 255)"] {
			border-color: @accent-color !important;
		}
		/* settings highlight thing */
		[style="background-color: rgb(38, 39, 45)"] {
			background-color: @base !important;
		}
		/* thin site: bluesky text */
		.r-yovm8p {
			color: @pine;
		}
		/* empty profile banner */
		.r-wuyfte {
			background-color: @pine;
		}
		/* "invalid handle" warning */
		[style*="color: rgb(236, 72, 104); border-color: rgb(209, 16, 67)"] {
			color: @love !important;
			border-color: @love !important;
		}
		/* end of feed text */
		.r-1521r3q {
			color: @muted;
		}
		/* mobile side drawer */
		[data-testid="drawer"] {
			background-color: @surface;
		}
		/* feedback */
		.r-m7buhn {
			background-color: @pine;
		}
		/* save, report, post modal button */
		[data-testid="sendReportBtn"],
		[data-testid="composerPublishBtn"],
		[data-testid="editProfileSaveBtn"] {
			background: unset !important;
			background-color: @accent-color !important;
			/* fix contrast issues */
			> div {
				color: @base !important;
			}
		}
		[data-testid="saveBtn"] {
			> div[style*="background-image: linear-gradient"] {
				background: unset !important;
				background-color: @accent-color !important;
				> div {
					color: @base !important;
				}
			}
		}
		// toast notifications (e.g. "copied to clipboard")
		.r-17c3jg3:has(> div[dir="auto"]) {
			background-color: @base !important;
			.r-jwli3a {
				color: @text !important;
			}
			> svg > path {
				fill: @text !important;
			}
		}
		/* draft "Discard" button */
		[style^="background-color: rgb(209, 16, 67)"] {
			background-color: @love !important;
		}
		/* the round gradient post button in the bottom right when the page is thinner than usual */
		[data-testid="composeFAB"] > div {
			background: unset !important;
			background-color: @accent-color !important;
			// fix contrast (inner symbol)
			.r-jwli3a {
				color: @base !important;
			}
		}
		/* blue text only button (e.g. cancel post button) */
		div[style*="color: rgb(52, 150, 254)"],
		div[style*="color: rgb(76, 162, 254)"] {
			color: @accent-color !important;
		}
		/* text color when writing a post */
		.ProseMirror,
		.ProseMirror-dark {
			color: @text;
		}
		/* some button background color (when hovering) */
		[style*="background-color: rgb(0, 44, 91)"],
		[style*="background-color: rgb(19, 63, 109)"] {
			background-color: fade(@accent-color, 30%) !important;
		}
		/* several white buttons */
		button[style*="background-color: rgb(255, 255, 255)"] when not(@lookup = dawn) {
			background-color: @text !important;
		}
		/* the white buttons text */
		[style*="color: rgb(0, 0, 0)"] {
			color: @base !important;
		}
		/* replace dark fill icons with crust ones */
		path[fill="#000000"] {
			fill: @base;
		}
		/* fixes a contrast issue when the suggested follows button is enabled (very ugly selector) */
		button[data-testid="suggestedFollowsBtn"][style*="background-color: rgb(255, 255, 255)"] > svg > path {
			fill: @surface !important;
		}
		/* text inside most buttons */
		button > div > div[style~="color: rgb(0, 0, 0)"] {
			color: @surface !important;
		}
		/* search bar text */
		[role="search"],
		[data-testid="confirmCodeInput"] {
			--placeholderTextColor: @subtle !important;
		}
		/* search bar icon */
		svg[style^="color: rgb(141, 142, 150)"] {
			color: @subtle !important;
		}
		/* small icons */
		path[fill="#ffffff"],
		path[fill="hsl(211, 20%, 95.3%)"] {
			fill: @text;
			& when (@lookup = dawn) {
				fill: @surface;
			}
		}
		/* more gray small icons (seems to only be the trash can/delete icon) */
		path[fill="#8D8E96"] {
			fill: @subtle;
		}
		/* settings button at the top of the timeline, hashtag button/icon at top of timeline */
		path[fill="hsl(211, 24%, 70%)"],
		path[fill="hsl(211, 20%, 62.4%)"] {
			fill: @subtle;
		}
		/* x invite codes available icon */
		div[style*="background-color: rgb(191, 225, 255)"],
		div[style*="background-color: rgb(1, 37, 97)"] {
			background-color: fadeout(@accent-color, 70%) !important;
			> svg > path[fill="#52acfe"] {
				fill: @accent-color;
			}
		}
		/* likes, reposts and comment counts/buttons under posts, maybe more */
		path[fill="hsl(211, 20%, 53%)"],
		[style*="color: rgb(111, 134, 159)"] {
			color: @subtle !important;
			fill: @subtle !important;
		}
		/* heart/like */
		.r-84gixx,
		.r-1i89l9k,
		div[style*="color: rgb(236, 72, 153)"],
		button[data-testid="toggleLikeBtn"] > svg:has(path[fill^="hsl(346,"]) // feed like button

		{
			color: @love !important;
			> path {
				fill: @love !important;
			}
		}
		/* repost */
		.r-5ld2xk,
		[style*="color: rgb(69, 237, 159)"] {
			color: @foam !important;
			> path {
				fill: @foam !important;
			}
		}
		/* tiny people icon on post view ("Everybody can reply") */
		path[fill="hsl(211, 24%, 43.6%)"],
		/* icon above "you have no lists" */ path[fill="hsl(211, 24%, 34.2%)"] {
			fill: @subtle;
		}
		/* onboarding: continue/next button */
		[data-testid="continueBtn"] {
			background-color: @accent-color !important;
		}
		[data-testid="continueBtn"] > div > div {
			color: @surface !important;
		}
		[data-testid="continueBtn"] > div > svg > path {
			fill: @surface !important;
		}
		/* pretty self explanatory, user mentions in the post create modal */
		.mention {
			color: @accent-color;
		}
		/* mentions in the notification tab (highlighted notifications) */
		div[style*="background-color: rgb(0, 17, 36)"],
		// dark
		div[style*="background-color: rgb(21, 41, 63)"],
		// dim
		div[style*="background-color: rgb(240, 247, 255)"] // light

		{
			background-color: fadeout(@accent-color, 70%) !important;
			.css-175oi2r:not([role="checkbox"] *) {
				background-color: transparent !important;
			}
		}
		/* generic blue background color inline (used for buttons in notifications tab) */
		button[style*="background-color: rgb(0, 133, 255)"] {
			background-color: @accent-color !important;
		}
		/* contrast fix for above */
		button[style*="background-color: rgb(0, 133, 255)"] > div > div {
			color: @surface !important;
		}
		/* other button in notifications tab, inner text */
		div[style*="color: rgb(82, 172, 254)"] {
			color: @accent-color !important;
		}
		/* "No notifications yet!" text in the notifications tab */
		div[style*="color: rgb(141, 142, 150)"] {
			color: @subtle !important;
		}
		/* login: wrong password highlight */
		.r-w7hjet {
			background-color: @love;
		}
		/* please verify your email popup (green checkmark) */
		circle[fill="#20BC07"] {
			fill: @foam;
		}
		/* toggle circle */
		[style*="background-color: rgb(185, 185, 193)"] {
			background-color: @muted !important;
		}
	}
}

/* deno-fmt-ignore */
@rose-pine: {
  @main: { @base: #191724; @surface: #1f1d2e; @overlay: #26233a; @muted: #6e6a86; @subtle: #908caa; @text: #e0def4; @love: #eb6f92; @gold: #f6c177; @rose: #ebbcba; @pine: #31748f; @foam: #9ccfd8; @iris: #c4a7e7; @highlightLow: #21202e; @highlightMed: #403d52; @highlightHigh: #524f67; };
  @moon: { @base: #232136; @surface: #2a273f; @overlay: #393552; @muted: #6e6a86; @subtle: #908caa; @text: #e0def4; @love: #eb6f92; @gold: #f6c177; @rose: #ea9a97; @pine: #3e8fb0; @foam: #9ccfd8; @iris: #c4a7e7; @highlightLow: #2a283e; @highlightMed: #44415a; @highlightHigh: #56526e; };
  @dawn: { @base: #faf4ed; @surface: #fffaf3; @overlay: #f2e9e1; @muted: #9893a5; @subtle: #797593; @text: #464261; @love: #b4637a; @gold: #ea9d34; @rose: #d7827e; @pine: #286983; @foam: #56949f; @iris: #907aa9; @highlightLow: #f4ede8; @highlightMed: #dfdad9; @highlightHigh: #cecacd; };
}

/* ==UserStyle==
@name           Rosé Pine for Phemex
@description    Soho vibes for Phemex
@version        1.0.0
@license        MIT
@author         Kainoa Kanter (https://github.com/ThatOneCalculator)
@namespace      https://github.com/rose-pine/
@homepageURL    https://github.com/rose-pine/userstyles
@updateURL      https://github.com/rose-pine/userstyles/raw/main/styles/phemex/rose-pine.user.less
@preprocessor   less

@var select lightVariant "Light Variant" ["main:Rosé Pine", "moon:Rosé Pine Moon", "dawn:Rosé Pine Dawn*"]
@var select darkVariant "Dark Variant" ["main:Rosé Pine*", "moon:Rosé Pine Moon", "dawn:Rosé Pine Dawn"]
@var select accentColor "Accent" ["love:Love*", "gold:Gold", "rose:Rose", "pine:Pine", "foam:Foam", "iris:Iris"]
==/UserStyle== */

@-moz-document domain("phemex.com") {
	:root.light {
		#rose-pine(@lightVariant);
	}
	:root.dark {
		#rose-pine(@darkVariant);
	}
	:root:not(.light, .dark) {
		@media (prefers-color-scheme: light) {
			#rose-pine(@lightVariant);
		}
		@media (prefers-color-scheme: dark) {
			#rose-pine(@darkVariant);
		}
	}

	#rose-pine(@variant) {
		@base: @rose-pine[@@variant][@base];
		@surface: @rose-pine[@@variant][@surface];
		@overlay: @rose-pine[@@variant][@overlay];
		@muted: @rose-pine[@@variant][@muted];
		@subtle: @rose-pine[@@variant][@subtle];
		@text: @rose-pine[@@variant][@text];
		@love: @rose-pine[@@variant][@love];
		@gold: @rose-pine[@@variant][@gold];
		@rose: @rose-pine[@@variant][@rose];
		@pine: @rose-pine[@@variant][@pine];
		@foam: @rose-pine[@@variant][@foam];
		@iris: @rose-pine[@@variant][@iris];
		@highlightLow: @rose-pine[@@variant][@highlightLow];
		@highlightMed: @rose-pine[@@variant][@highlightMed];
		@highlightHigh: @rose-pine[@@variant][@highlightHigh];
		color-scheme: if(@variant = dawn, light, dark);
		@accent-color: @rose-pine[@@variant][@@accentColor];
		accent-color: @accent-color !important;

		::selection {
			background-color: fade(@accent-color, 30%);
		}

		--B0: @surface;
		--B1: @base;
		--B1H: @overlay;
		--B2: @overlay;
		--B3: @overlay;
		--B3H: @highlightMed;
		--B4: @highlightMed;
		--B5: @highlightHigh;
		--T1: @text;
		--T2: @subtle;
		--T3: @muted;
		--T4: @subtle;
		--T5: @muted;
		--T6: @muted;
		--BD: @highlightMed;
		--blue: @pine;
		--buy: @foam;
		--sell: @love;
		--ASK1: fade(@love, 20%);
		--ASK2: fade(@love, 20%);
		--BID1: fade(@pine, 20%);
		--BID2: fade(@pine, 20%);
		--UPF: fade(@pine, 20%);
		--DWF: fade(@pine, 20%);
		--RTF: fade(@text, 5%);
		--F26: fade(@love, 16%);
		--B25: @pine;
		--TD5: @text;

		& when (@variant = dawn) {
			--TW: @highlightLow;
			--B1: @surface;
			--B25: fade(@pine, 6%);
			--TD5: @pine;
		}

		& when not(@variant = dawn) {
			--B25: @foam;
		}

		.warning,
		.liq {
			color: @gold;
		}

		.sub-img.ml4 {
			display: none;
		}

		.funding {
			color: @pine;
		}

		.badge,
		.limit {
			background: @pine;
			color: @text;
		}

		.wrap {
			background: @highlightMed;
			margin: 0 6px;
		}

		.market {
			background: @iris;
			color: @surface;
		}
	}
}

/* deno-fmt-ignore */
@rose-pine: {
	@main: { @base: #191724; @surface: #1f1d2e; @overlay: #26233a; @muted: #6e6a86; @subtle: #908caa; @text: #e0def4; @love: #eb6f92; @gold: #f6c177; @rose: #ebbcba; @pine: #31748f; @foam: #9ccfd8; @iris: #c4a7e7; @highlightLow: #21202e; @highlightMed: #403d52; @highlightHigh: #524f67; };
	@moon: { @base: #232136; @surface: #2a273f; @overlay: #393552; @muted: #6e6a86; @subtle: #908caa; @text: #e0def4; @love: #eb6f92; @gold: #f6c177; @rose: #ea9a97; @pine: #3e8fb0; @foam: #9ccfd8; @iris: #c4a7e7; @highlightLow: #2a283e; @highlightMed: #44415a; @highlightHigh: #56526e; };
	@dawn: { @base: #faf4ed; @surface: #fffaf3; @overlay: #f2e9e1; @muted: #9893a5; @subtle: #797593; @text: #464261; @love: #b4637a; @gold: #ea9d34; @rose: #d7827e; @pine: #286983; @foam: #56949f; @iris: #907aa9; @highlightLow: #f4ede8; @highlightMed: #dfdad9; @highlightHigh: #cecacd; };
}

/* ==UserStyle==
@name           Rosé Pine for LeetCode
@description    Soho vibes for LeetCode
@version        1.0.0
@license        MIT
@author         Rosé Pine
@namespace      https://github.com/rose-pine/
@homepageURL    https://github.com/rose-pine/userstyles
@updateURL      https://github.com/rose-pine/userstyles/raw/main/styles/leetcode/rose-pine.user.less
@preprocessor   less

@var select lightVariant "Light Variant" ["dawn:Rosé Pine Dawn*", "main:Rosé Pine", "moon:Rosé Pine Moon"]
@var select darkVariant "Dark Variant" ["main:Rosé Pine*", "moon:Rosé Pine Moon", "dawn:Rosé Pine Dawn"]
@var select accentColor "Accent" ["love:Love*", "gold:Gold", "rose:Rose", "pine:Pine", "foam:Foam", "iris:Iris"]
==/UserStyle== */

@-moz-document domain("leetcode.com"), domain("leetcode.cn") {
	:root {
		@media (prefers-color-scheme: light) {
			#rose-pine(@lightVariant);
		}
		@media (prefers-color-scheme: dark) {
			#rose-pine(@darkVariant);
		}
	}

	:root[data-theme="dark"] {
		#rose-pine(@darkVariant);
	}
	:root[data-theme="light"] {
		#rose-pine(@lightVariant);
	}

	#rose-pine(@variant) {
		@base: @rose-pine[@@variant][@base];
		@surface: @rose-pine[@@variant][@surface];
		@overlay: @rose-pine[@@variant][@overlay];
		@muted: @rose-pine[@@variant][@muted];
		@subtle: @rose-pine[@@variant][@subtle];
		@text: @rose-pine[@@variant][@text];
		@love: @rose-pine[@@variant][@love];
		@gold: @rose-pine[@@variant][@gold];
		@rose: @rose-pine[@@variant][@rose];
		@pine: @rose-pine[@@variant][@pine];
		@foam: @rose-pine[@@variant][@foam];
		@iris: @rose-pine[@@variant][@iris];
		@highlightLow: @rose-pine[@@variant][@highlightLow];
		@highlightMed: @rose-pine[@@variant][@highlightMed];
		@highlightHigh: @rose-pine[@@variant][@highlightHigh];
		@accent-color: @rose-pine[@@variant][@@accentColor];

		color-scheme: if(@variant = dawn, light, dark);

		--bg-dark: @highlightLow;
		--bg-code: @base;
		--bg: @surface;
		--bg-2: @overlay;
		--bg-3: @highlightMed;
		--bg-4: @highlightHigh;
		--highlight-1: @overlay;
		--highlight-2: @highlightMed;
		--highlight-3: @highlightHigh;
		--blue-accent: @foam;
		--text: @text;
		--text-dark: @subtle;
		--cyan: @foam;
		--blue: @pine;
		--blue-dark: @pine;
		--orange: @gold;
		--orange-dark: @gold;
		--red: @love;
		--red-dark: @love;
		--green: @foam;
		--green-dark: @foam;
		--purple: @iris;
		--accent: @accent-color;

		/* General */
		--text-primary: var(--text);
		--text-secondary: var(--text);
		--fill-secondary: var(--bg-2);
		--fill-quaternary: var(--bg);
		--text-sd-success: var(--red);
		--text-label-4: var(--red);
		--text-reverse: var(--bg-dark);
		--fill-primary: color-mix(in srgb, var(--blue), var(--bg-dark) 75%);
		--fill-tertiary: var(--bg-2);
		--border-primary: var(--blue);
		--border-secondary: var(--bg-2);
		--border-tertiary: var(--bg-2);
		--border-quaternary: var(--bg);

		/* Code */
		--layer-01: var(--bg);
		--layer-02: var(--bg-2);
		--layer-bg-gray: var(--bg-dark);

		/* Submission graph */
		--green-80: fade(@accent-color, 80%);
		--green-60: fade(@accent-color, 60%);
		--green-40: fade(@accent-color, 40%);
		--green-20: fade(@accent-color, 20%);

		::selection {
			color: var(--text);
			background: var(--highlight-3);
		}

		:is(.dark body) {
			background: var(--bg-dark);
			color: var(--text);
		}

		:is(.dark .dark\:bg-\[\#1a1a1a\]) {
			background: var(--bg-dark);
		}

		:is(.dark .dark\:bg-\[\#333333\]) {
			background: var(--bg);
		}

		:is(.dark .dark\:bg-gray-100),
		:is(.dark .dark\:text-gray-60) {
			color: var(--text-dark);
		}

		:is(.dark .dark\:text-green-60) {
			color: var(--accent);
		}

		:is(.dark .dark\:bg-white) {
			background: var(--text);
		}

		:is(.dark .dark\:bg-\[linear-gradient\(rgba\(0\,0\,0\,0\)\,\#1A1A1A\)\]) {
			background-image: linear-gradient(#0000, var(--bg-dark));
		}

		:is(.dark .dark\:bg-dark-layer-bg) {
			background: var(--bg-dark);
		}

		:is(.dark .dark\:bg-dark-layer-1),
		:is(.dark .dark\:bg-dark-layer-2),
		:is(.dark .dark\:bg-dark-layer-3) {
			background: var(--bg);
		}

		:is(.dark .dark\:bg-dark-paper) {
			background: var(--bg-dark);
		}

		:is(.dark .dark\:text-dark-gray-6) {
			color: var(--text-dark);
		}

		:is(.dark .dark\:border-dark-divider-border-2) {
			border-color: var(--bg-2);
		}

		.border-dark-label-3 {
			border-color: var(--text-dark);
		}

		:is(.dark .dark\:bg-dark-fill-1),
		:is(.dark .dark\:bg-dark-fill-2),
		:is(.dark .dark\:bg-dark-fill-3),
		:is(.dark .dark\:hover\:bg-dark-fill-3:hover) {
			background: var(--highlight-1);
		}

		:is(.dark .dark\:bg-dark-fill-4),
		:is(.dark .dark\:hover\:bg-dark-fill-4:hover) {
			background: var(--highlight-1);
		}

		:is(.dark .dark\:bg-dark-gray-5) {
			background: var(--bg-4);
		}

		:is(.dark .dark\:hover\:bg-dark-fill-2:hover) {
			background: var(--bg-2);
		}

		:is(.dark .dark\:focus\:bg-dark-fill-2:focus) {
			background: var(--bg-3);
		}

		:is(.dark .dark\:text-dark-label-1),
		:is(.dark .dark\:hover\:text-dark-label-1:hover),
		.text-label-1,
		.text-label-1:hover,
		:is(.dark .dark\:text-dark-label-2),
		:is(.dark .dark\:hover\:text-dark-label-2:hover),
		:is(.dark .dark\:text-dark-label-3) {
			color: var(--text);
		}

		:is(.dark .dark\:hover\:text-dark-label-3:hover),
		:is(.dark .dark\:text-dark-label-4) {
			color: var(--text-dark);
		}

		:is(.dark .dark\:text-dark-label-r) {
			color: var(--bg-dark);
		}

		:is(.dark .dark\:text-dark-gray-4) {
			color: var(--bg-dark);
		}

		:is(.dark .dark\:text-dark-gray-5) {
			color: var(--text-dark);
		}

		:is(.dark .dark\:text-gray-7) {
			color: var(--text-dark);
		}

		:is(.dark .dark\:text-text-primary) {
			color: var(--text);
		}

		:is(.dark .dark\:text-text-secondary) {
			color: var(--text);
		}

		:is(.dark .dark\:text-text-tertiary) {
			color: var(--text-dark);
		}

		/* Loading Content (lc) */
		:is(.dark .dark\:bg-dark-lc-layer-01) {
			background: var(--bg-dark);
		}

		:is(.dark .dark\:bg-dark-lc-fill-01),
		:is(.dark .dark\:hover\:bg-dark-lc-fill-01:hover) {
			background: var(--bg-4);
		}

		:is(.dark .dark\:bg-dark-lc-fill-02),
		:is(.dark .dark\:hover\:bg-dark-lc-fill-02:hover) {
			background: var(--bg-2);
		}

		:is(.dark .dark\:bg-dark-lc-fill-03),
		:is(.dark .dark\:hover\:bg-dark-lc-fill-03:hover) {
			background: var(--bg-2);
		}

		:is(.dark .dark\:bg-dark-lc-fill-04),
		:is(.dark .dark\:hover\:bg-dark-lc-fill-04:hover) {
			background: var(--bg-2);
		}

		:is(.dark .dark\:bg-dark-lc-background-index) {
			background: var(--bg-dark);
		}

		:is(.dark .dark\:border-dark-lc-fill-01) {
			background: var(--bg);
		}

		:is(.dark .dark\:hover\:bg-dark-lc-fill-02) {
			background: var(--highlight-1);
		}

		:is(.dark .dark\:hover\:bg-dark-lc-fill-02:hover) {
			background: var(--bg-2);
		}

		:is(.dark .dark\:text-dark-lc-text-primary) {
			color: var(--text);
		}

		:is(.dark .dark\:text-dark-lc-text-secondary) {
			color: var(--text-dark);
		}

		:is(.dark .dark\:text-dark-lc-text-tertiary) {
			color: var(--text-dark);
		}

		:is(.dark .dark\:text-dark-lc-text-quaternary) {
			color: var(--text-dark);
		}

		:is(.dark .dark\:border-dark-lc-fill-02) {
			border-color: var(--bg-2);
		}

		:is(.dark .dark\:text-dark-lc-icon-secondary),
		:is(.dark .dark\:text-dark-lc-icon-tertiary) {
			color: var(--text-dark);
		}

		:is(.dark .dark\:stroke-dark-lc-fill-02) {
			stroke: var(--bg-2);
		}

		:is(.dark .group:hover .dark\:group-hover\:text-dark-blue) {
			color: var(--blue);
		}

		:is(.dark .dark\:text-dark-blue-s) {
			color: var(--blue);
		}

		:is(.dark .dark\:bg-dark-overlay-3) {
			background: var(--bg);
		}

		:is(.dark .dark\:bg-dark-blocker) {
			background-color: var(--bg);
		}

		.bg-overlay-2,
		.bg-overlay-3,
		.bg-overlay-4,
		.bg-paper {
			background: var(--bg);
		}

		/* Vim statusline */
		:is(.dark .dark\:bg-dark-gray-2),
		:is(.dark .dark\:bg-dark-gray-2) input {
			background-color: var(--highlight-1);
			padding-left: 10px;
		}

		/* Table */
		:is(.dark .dark\:odd\:bg-dark-layer-1:nth-child(2n+1)) {
			background: var(--bg-dark);
		}

		:is(.dark .dark\:odd\:bg-dark-layer-bg:nth-child(2n+1)) {
			background: var(--bg-dark);
		}

		:is(.dark .dark\:even\:bg-dark-fill-4:nth-child(2n)) {
			background: var(--bg);
		}

		.even\:bg-overlay-1:nth-child(2n) {
			background: var(--bg);
		}

		tr:nth-of-type(2n+1) {
			background: var(--bg-dark) !important;
		}

		tr:nth-of-type(2n) {
			background: var(--bg) !important;
		}

		.grid > :is(.dark .dark\:bg-dark-lc-fill-01),
		:is(.dark .dark\:hover\:bg-dark-lc-fill-01:hover) {
			background: var(--highlight-1);
		}

		/* Transparents */
		.bg-gray-8 {
			background-color: var(--bg-dark);
		}

		:is(.dark .dark\:text-dark-lc-icon-primary) {
			background-color: rgba(0, 0, 0, 0.2);
		}

		.bg-gradient-to-l {
			background-image: linear-gradient(to right, #0000, var(--bg-dark));
		}

		:is(.dark .dark\:bg-\[linear-gradient\(to_right\,rgba\(0\,0\,0\,0\)\,\#282828_70\%\)\]),
		.flexlayout__tabset-overflowed .flexlayout__tabset_tabbar_inner::after {
			background-image: linear-gradient(to right, #0000, var(--bg));
		}

		.flexlayout__tabset-overflowed .flexlayout__tabset_tabbar_inner::before {
			background-image: linear-gradient(to left, #0000, var(--bg));
		}

		/* Code */
		.mtk1 {
			color: var(--text);
		}

		.mtk3 {
			color: var(--text-dark);
		}

		.mtk4 {
			color: var(--blue);
		}

		.mtk7 {
			color: var(--orange);
		}

		.mtk10 {
			color: var(--green-dark);
		}

		.mtk11 {
			color: var(--orange);
		}

		.mtk14 {
			color: var(--blue-accent);
		}

		.monaco-editor .line-numbers.active-line-number {
			color: var(--text);
		}

		.monaco-editor .line-numbers {
			color: var(--text-dark);
		}

		.dark .elfjS code {
			background-color: var(--bg-2);
			border-color: var(--bg-2);
			color: var(--text);
		}

		.monaco-scrollable-element > .scrollbar > .slider {
			background: var(--bg-2);
		}

		.decorationsOverviewRuler {
			display: none;
		}

		.current-line {
			background: var(--highlight-1);
			border-color: var(--highlight-1) !important;
		}

		.core-guide {
			box-shadow: 2px 0 0 0 var(--highlight-2) inset !important;
		}

		.cursor {
			color: var(--text);
		}

		.bg-sd-accent {
			background-color: var(--highlight-1);
		}

		.text-sd-green-500 {
			color: var(--accent);
		}

		.text-sd-yellow-500 {
			color: var(--accent);
		}

		.bg-sd-green-500 {
			background-color: var(--accent);
		}

		.bg-sd-card {
			background: var(--bg);
		}

		.bg-brand-orange {
			background: var(--accent);
		}

		.svg-inline--fa.fa-star path {
			fill: var(--accent);
		}

		:is(.dark .dark\:text-message-success) {
			color: var(--accent);
		}

		.text-sd-blue-500 {
			color: var(--accent);
		}

		.hover\:bg-sd-secondary\/80 {
			background: var(--highlight-2);
		}

		.hover\:bg-sd-secondary\/80:hover {
			background: var(--highlight-1);
		}

		.ace-tm,
		.ace-tm .ace_gutter {
			background: var(--bg);
			color: var(--text);
		}

		.editor {
			border-color: var(--highlight-1);
		}

		body,
		#explore-app {
			background: var(--bg-dark);
		}

		#leetcode-navbar,
		#footer-root,
		footer,
		footer > div,
		footer li::after {
			background: var(--bg) !important;
			border: none !important;
		}

		footer span,
		footer a {
			color: var(--text-dark) !important;
		}

		/* Removes unnecessary premium buttons */
		a[href="/subscribe/?ref=lp_pl&source=qd"],
		a[href="/subscribe/?ref=lp_pl&source=ot"] {
			display: none;
		}

		a[href="/subscribe?ref=nb_npl&source=nav-icon"] svg {
			display: none;
		}

		a[href*="/subscribe/?ref=qd3_cs&slug="] {
			display: none;
		}

		strong {
			color: var(--text) !important;
		}

		input,
		textarea {
			&::placeholder {
				color: var(--text-dark) !important;
			}
		}

		::highlight {
			background-color: var(--text) !important;
		}

		* {
			scrollbar-color: var(--bg-2) var(--bg);
		}

		/* Chevron down icon color */
		svg.origin-center.transition-transform {
			fill: var(--bg-3);
		}

		/* Contest Page */
		html {
			background: var(--bg-dark);
		}

		.title,
		.col-sm-8.col-md-9 {
			color: var(--text);
		}

		.callout.callout-default,
		.list-group-item,
		.heading {
			background: var(--bg);
			color: var(--text);
			border-color: var(--bg-3);
		}

		.ranking-more-btn {
			background: var(--bg);
			color: var(--text);
		}

		.list-group-item.heading {
			color: var(--text);
			background-color: var(--bg-dark);
			border-color: var(--bg-3);
		}

		.list-group-item a,
		td a,
		b a,
		li a {
			color: var(--blue);
		}

		.badge {
			color: var(--text);
			background-color: var(--bg-3);
		}

		.panel-default {
			border-color: var(--bg-3);
		}

		.panel-default > .panel-heading {
			color: var(--text);
			background-color: var(--bg-dark);
			border-color: var(--bg-3);
		}

		.table > thead > tr > th {
			border-bottom: 2px solid var(--bg-3);
		}

		.table > tbody > tr > td {
			border-top: 1px solid var(--bg-3);
		}

		.contest-detail-base .ranking-list .panel-body .ranking-more-btn {
			border-top: 2px solid var(--bg-3);
		}

		.contest-detail-base .ranking-list .panel-body .ranking-more-btn:hover {
			background: var(--bg-2);
		}

		.contest-detail-base .callout {
			background: var(--bg);
			color: var(--text);
			border-color: var(--bg-3);
		}

		.contest-detail-base .callout a {
			color: var(--blue);
		}

		/* Discuss Page */
		#discuss-container {
			background: var(--bg-dark);
		}

		.header__a1sK {
			background: var(--bg);
		}

		.header__a1sK a:hover,
		.category-link__1lP8.active-category__37NE,
		.subheader__3zA6 label {
			color: var(--text);
		}

		.subheader__3zA6 {
			background: var(--bg-code);
		}

		.input__2o8B {
			background: var(--bg-2);
			border: none;
		}

		.topic-list-content__3Win {
			background: var(--bg);
			color: var(--text);
		}

		.topic-title__3LYM,
		.icon__1Md2.pinned-icon__1ZAy,
		.no__1erK {
			color: var(--text);
		}

		.topic-info__tdz0 span,
		.topic-info__tdz0 a {
			color: var(--text-dark);
		}

		.icon__1Md2.icon__3CsQ {
			color: var(--bg-4);
		}

		.e5i1odf1.css-zywons-Container-RoundedTagFilter.e5i1odf0 {
			background: var(--bg);
		}

		.css-xvf81j-TagsTitle.e5i1odf3,
		.css-wgldzj-Pane-LeftPane.e5i1odf2 span,
		.css-154bklu-Pane.e5i1odf1 span {
			color: var(--text);
		}

		.css-g96614,
		.tag__2FfF,
		.ant-popover-inner-content {
			background: var(--bg-3);
			color: var(--text);
		}

		.css-wgldzj-Pane-LeftPane.e5i1odf2 {
			background: var(--bg-3);
			border: none;
		}

		.css-154bklu-Pane.e5i1odf1 {
			background: var(--bg-2);
		}

		.css-2mbh4k-TagButton.e5i1odf3 {
			border-color: var(--bg-4);
			border-radius: 0px;
		}

		.ant-pagination-item {
			background: var(--bg-3);
		}

		.ant-pagination-item a {
			color: var(--text);
		}

		.pagination-prev a {
			background: var(--bg-3);
		}

		.css-10yicc7-Category.e5i1odf1 {
			background: var(--bg-4);
		}

		.css-10yicc7-Category.e5i1odf1 h1,
		.css-1pz7gg5:hover,
		.icon__1Md2.css-1mdt1kb-BlockIcon.e5i1odf2 {
			color: var(--text);
		}

		.css-1pz7gg5:hover .e5i1odf2 {
			color: #fff;
		}

		.topic-container__3Kpd {
			background: var(--bg);
			color: var(--text);
		}

		.post-info__1K06,
		.user-info__2b-x span a,
		.name__2jm2,
		.sorts__3Wh1 label {
			color: var(--text);
