			--light-theme-base-color: @text !important;
			--light-theme-text-color: @text !important;
			--light-theme-secondary-color: @subtle !important;
			--light-theme-disabled-color: @subtle !important;
			--light-theme-divider-color: @muted !important;
			--dark-theme-background-color: @surface !important;
			--dark-theme-base-color: @text !important;
			--dark-theme-text-color: @text !important;
			--dark-theme-secondary-color: @subtle !important;
			--dark-theme-disabled-color: @subtle !important;
