		ytd-macro-markers-list-item-renderer {
			--ytd-macro-markers-list-item-background-color: @overlay !important;
			--ytd-macro-markers-list-item-title-color: @text !important;
			--ytd-macro-markers-list-item-secondary-color: @subtle !important;
			--ytd-macro-markers-list-item-timestamp-background-color: @overlay
        !important;
		}

		ytd-playlist-panel-video-renderer {
			--yt-lightsource-section2-color: @overlay !important;
			--yt-lightsource-section4-color: @overlay !important;
			--yt-lightsource-primary-title-color: @text !important;
