		@overlay: @rose-pine[@@variant][@overlay];
		@muted: @rose-pine[@@variant][@muted];
		@subtle: @rose-pine[@@variant][@subtle];
		@text: @rose-pine[@@variant][@text];
		@love: @rose-pine[@@variant][@love];
		@gold: @rose-pine[@@variant][@gold];
		@rose: @rose-pine[@@variant][@rose];
		@pine: @rose-pine[@@variant][@pine];
		@foam: @rose-pine[@@variant][@foam];
		@iris: @rose-pine[@@variant][@iris];
		@highlightLow: @rose-pine[@@variant][@highlightLow];
		@highlightMed: @rose-pine[@@variant][@highlightMed];
		@highlightHigh: @rose-pine[@@variant][@highlightHigh];
		@accent: @rose-pine[@@variant][@@accentColor];
		color-scheme: if(@variant = dawn, light, dark);

		background-color: @surface !important;
		color: @text !important;

		/* Ambient mode */
		#cinematics {
			mix-blend-mode: lighten;
		}

		.mobile-topbar-header[data-mode="watch"],
		ytm-mobile-topbar-renderer:not([ambient-topbar]) {
			background: @surface;
		}

		.mobile-topbar-header[data-mode="watch"] .mobile-topbar-logo,
		.mobile-topbar-header[data-mode="watch"] .mobile-topbar-title,
		.mobile-topbar-header[data-mode="watch"] .mobile-topbar-header-content {
			color: @text;
		}

		.yt-spec-bottom-sheet-layout__bottom-sheet-renderer-container,
		.modern-styling {
			background: @overlay;
		}

		.yt-spec-bottom-sheet-layout__bottom-sheet-layout-header-wrapper {
			border-bottom-color: @overlay;
		}

		.yt-spec-bottom-sheet-layout__bottom-sheet-content {
			color: @text;
		}

		/* Comment box */
		.engagement-panel-container {
			background: @surface;
		}

		/* Bottom bar */
		ytm-pivot-bar-renderer {
			background: @surface;
			color: @text;
			border-top-color: @overlay;
		}

		/* Chips */
		.chip-bar {
			background-color: @surface;
		}

		[chip-style*="STYLE_"] {
			.chip-container {
				color: @text;
				background-color: @overlay;
			}

			&.selected .chip-container {
				color: @base;
				background-color: @accent;
			}
		}

		/* Buttons */

		.yt-spec-touch-feedback-shape--touch-response {
			.yt-spec-touch-feedback-shape__fill {
				background-color: @text;
			}

			.yt-spec-touch-feedback-shape__stroke {
				border-color: @overlay;
			}
		}

		.yt-spec-touch-feedback-shape--overlay-touch-response-inverse .yt-spec-touch-feedback-shape__fill {
			background-color: @accent;
		}
		.yt-spec-touch-feedback-shape--overlay-touch-response .yt-spec-touch-feedback-shape__fill {
			background-color: @text;
		}
	}
}

