/* ==UserStyle==
@name           Rosé Pine for ChatGPT
@description    Soho vibes for ChatGPT
@version        1.1.1
@license        MIT
@author         Jenish Boricha (https://github.com/jenishboricha)
@namespace      https://github.com/rose-pine/
@homepageURL    https://github.com/rose-pine/userstyles
@updateURL      https://github.com/rose-pine/userstyles/raw/main/styles/chatgpt/rose-pine.user.less
@preprocessor   less

@var select lightFlavor "Light Palette" ["dawn:Rosé Pine Dawn*"]
@var select darkFlavor "Dark Palette" ["main:Rosé Pine*", "moon:Rosé Pine Moon"]
@var select accentColor "Accent Color" ["rose:Rose*", "love:Love", "gold:Gold", "pine:Pine", "foam:Foam", "iris:Iris"]
@var select codeFontFamily "Code Font Family" ["default:Default*", "cascadia:Cascadia Code", "firacode:Fira Code", "geist:Geist Mono", "ibm:IBM Plex Mono", "inconsolata:Inconsolata", "jetbrains:JetBrains Mono", "source:Source Code Pro", "space:Space Mono", "ubuntu:Ubuntu Sans Mono"]
@var range codeFontSize "Code Font Size" [14, 12, 20, 1, "px"]
@var range codeLineHeight "Code Line Height" [1.4, 1.2, 2.0, 0.05]
@var checkbox enableCodeBlocks "Enable Code Block Theme" 1
==/UserStyle== */

@-moz-document domain("chatgpt.com"), domain("auth.openai.com") {
	/* Google Web Font Imports */
	@import url('https://fonts.googleapis.com/css2?family=Cascadia+Code:wght@400;500;600&family=Fira+Code:wght@400;500;600&family=Geist+Mono:wght@400;500;600&family=IBM+Plex+Mono:wght@400;500;600&family=Inconsolata:wght@400;600&family=JetBrains+Mono:ital,wght@0,400;0,500;0,600;1,400&family=Source+Code+Pro:wght@400;500;600&family=Space+Mono:wght@400;700&family=Ubuntu+Sans+Mono:wght@400;500;700&display=swap');

	/* deno-fmt-ignore */
	@rose-pine: {
        @main: { @base: #191724; @surface: #1f1d2e; @overlay: #26233a; @muted: #6e6a86; @subtle: #908caa; @text: #e0def4; @love: #eb6f92; @gold: #f6c177; @rose: #ebbcba; @pine: #31748f; @foam: #9ccfd8; @iris: #c4a7e7; @highlightLow: #21202e; @highlightMed: #403d52; @highlightHigh: #524f67; };
        @moon: { @base: #232136; @surface: #2a273f; @overlay: #393552; @muted: #6e6a86; @subtle: #908caa; @text: #e0def4; @love: #eb6f92; @gold: #f6c177; @rose: #ea9a97; @pine: #3e8fb0; @foam: #9ccfd8; @iris: #c4a7e7; @highlightLow: #2a283e; @highlightMed: #44415a; @highlightHigh: #56526e; };
        @dawn: { @base: #faf4ed; @surface: #fffaf3; @overlay: #f2e9e1; @muted: #9893a5; @subtle: #797593; @text: #464261; @love: #b4637a; @gold: #ea9d34; @rose: #d7827e; @pine: #286983; @foam: #56949f; @iris: #907aa9; @highlightLow: #f4ede8; @highlightMed: #dfdad9; @highlightHigh: #cecacd; };
    }

	/* ChatGPT Rules */
	.light {
		#rose-pine(@lightFlavor, @accentColor);
	}

	.dark {
		#rose-pine(@darkFlavor, @accentColor);
	}

	#rose-pine(@flavor, @accent) {
		@raw-base: @rose-pine[@@flavor][@base];
		@raw-surface: @rose-pine[@@flavor][@surface];

		@base: if(@flavor = dawn, @raw-surface, @raw-base);
		@surface: if(@flavor = dawn, @raw-base, @raw-surface);

		@overlay: @rose-pine[@@flavor][@overlay];
		@muted: @rose-pine[@@flavor][@muted];
		@subtle: @rose-pine[@@flavor][@subtle];
		@text: @rose-pine[@@flavor][@text];
		@love: @rose-pine[@@flavor][@love];
		@gold: @rose-pine[@@flavor][@gold];
		@rose: @rose-pine[@@flavor][@rose];
		@pine: @rose-pine[@@flavor][@pine];
		@foam: @rose-pine[@@flavor][@foam];
		@iris: @rose-pine[@@flavor][@iris];
		@highlightLow: @rose-pine[@@flavor][@highlightLow];
		@highlightMed: @rose-pine[@@flavor][@highlightMed];
		@highlightHigh: @rose-pine[@@flavor][@highlightHigh];

		@accent-color: @rose-pine[@@flavor][@@accent];

		/* Font Mapping */
		@default-mono-stack: ~"ui-monospace, SFMono-Regular, 'Roboto Mono', Menlo, Monaco, 'Liberation Mono', 'DejaVu Sans Mono', 'Courier New', monospace";

		@font-stack: if(@codeFontFamily = cascadia,
			~"'Cascadia Code', 'Cascadia Mono', monospace",
			if(@codeFontFamily = firacode,
			~"'Fira Code', 'FiraCode Nerd Font', monospace",
			if(@codeFontFamily = geist, ~"'Geist Mono', monospace",
			if(@codeFontFamily = ibm, ~"'IBM Plex Mono', monospace",
			if(@codeFontFamily = inconsolata, ~"'Inconsolata', monospace",
			if(@codeFontFamily = jetbrains,
			~"'JetBrains Mono', 'JetBrainsMono Nerd Font', monospace",
			if(@codeFontFamily = source, ~"'Source Code Pro', monospace",
			if(@codeFontFamily = space, ~"'Space Mono', monospace",
			if(@codeFontFamily = ubuntu,
			~"'Ubuntu Sans Mono', 'Ubuntu Mono', monospace",
			@default-mono-stack)))))))));

		* {
			--text-primary: @text;
			--text-secondary: @subtle;
			--text-tertiary: @muted;
			--text-quaternary: @highlightHigh;
			--bg-primary: @base;
			--bg-secondary: @surface;
			--bg-tertiary: @overlay;

			--bg-secondary-surface: @surface;

			--bg-elevated-primary: @base;
			--bg-elevated-secondary: @surface;

			--bg-tooltip: @base;

			--main-surface-primary: @base;
			--main-surface-secondary: @surface;
			--main-surface-tertiary: @overlay;

			/* Set Composer Token directly to Surface */
			--composer-surface-primary: @surface !important;
			--composer-surface-secondary: @overlay !important;

			--interactive-bg-secondary-hover: @overlay;
			--interactive-bg-secondary-press: @surface;

			--interactive-label-accent-default: @accent-color;

			--border-light: @highlightLow;
			--border-default: @highlightMed;
			--border-medium: @highlightHigh;
			--interactive-border-focus: @subtle;

			--theme-user-msg-bg: @surface;
			--theme-user-msg-text: @text;
			--theme-submit-btn-bg: @accent-color;
			--theme-submit-btn-text: @base;

			--theme-secondary-btn-bg: @overlay;
			--theme-secondary-btn-text: @text;

			--sidebar-surface: @surface;
			--sidebar-surface-primary: @surface;

			--surface-hover: @overlay;

			--icon-tertiary: @subtle;

			--text-status-error: @love;

			--shadow-color-1: fade(@surface, 50%);
			--shadow-color-2: fade(@text, 80%);

			.__menu-item[data-sidebar-item] {
				--menu-item-highlighted: @overlay;
			}

			.__menu-item[data-color="danger"] {
				--menu-item-highlighted: fade(@love, 20%);
				--menu-item-active: fade(@love, 30%);
				--menu-item-open: fade(@love, 30%);
			}

			/* Clear hardcoded background overrides on prompt */
			#prompt-textarea {
				background-color: transparent !important;
				color: @text !important;
			}

			nav,
			aside,
			[data-sidebar],
			div[class*="group/sidebar"],
			div[class*="sidebar-container"],
			div[class*="bg-token-sidebar-surface"] {
				border-top-left-radius: 0 !important;
				border-bottom-left-radius: 0 !important;
			}

			pre {
				background-color: transparent !important;
				--code-block-surface: transparent !important;
				--main-surface-secondary: transparent !important;
				overflow: auto !important;
			}

			pre,
			pre code,
			.cm-editor,
			.cm-scroller,
			.cm-content,
			.cm-line,
			#code-block-viewer {
				font-family: @font-stack !important;
				font-size: @codeFontSize !important;
				line-height: @codeLineHeight !important;
			}

			pre > div,
			div.markdown-new-styling pre div[class*="code-block-surface"] {
				--code-block-surface: @surface !important;
				--main-surface-secondary: @surface !important;
				background-color: @surface !important;
				border-radius: 1.5rem !important;
				overflow-x: auto !important;
				overflow-y: hidden !important;
			}

			[data-radix-popper-content-wrapper] {
				background-color: transparent !important;
				border: none !important;
				box-shadow: none !important;
			}

			[role="tooltip"],
			.radix-tooltip-content,
			div[data-state][class*="tooltip"] {
				color: @text !important;
				background-color: @surface !important;
				border: 1px solid @highlightMed !important;

				span,
				p,
				div {
					color: @text !important;
				}

				kbd,
				.text-token-text-tertiary,
				.text-token-text-secondary {
					color: @subtle !important;
				}

				.bg-token-main-surface-primary,
				.bg-black,
				[class*="bg-"] {
					background-color: @overlay !important;
					color: @text !important;
				}
			}

			code:not(pre > code) {
				background-color: @overlay !important;
				color: @text !important;
				font-family: @font-stack !important;
				font-size: 0.9em !important;
			}

			code[class*="language-"],
			pre[class*="language-"] {
				color: @text !important;
			}

			/* Code Output Theme */
			& when (@enableCodeBlocks = 1) {
				#code-block-viewer,
				.cm-editor,
				.cm-scroller,
				.cm-content,
				.cm-line {
					border-radius: inherit !important;
					background-color: @surface !important;
					color: @text !important;
				}

				pre code,
				.cm-editor,
				.light\:cm-light,
				.dark\:cm-light {
					background-color: @surface !important;
					color: @text !important;
					border-radius: inherit !important;
				}

				pre .sticky,
				pre .sticky > div,
				pre div[class*="code-block-surface"] {
					background-color: @surface !important;
					color: @text !important;
					border-top-left-radius: inherit !important;
					border-top-right-radius: inherit !important;
				}

				pre .sticky button:hover {
					background-color: fade(@highlightHigh, 30%) !important;
				}

				pre code,
				.cm-editor,
				.cm-content,
				.cm-line,
				.light\:cm-light,
				.dark\:cm-light {
					.ͼe,
					.ͼt,
					span.ͼe,
					span.ͼt,
					span[class*="comment"] {
						color: @muted !important;
					}

					.ͼf,
					.ͼu,
					.ͼ13,
					.ͼd,
					span.ͼf,
					span.ͼu,
					span.ͼ13,
					span.ͼd,
					span[class*="preprocessor"],
					span[class*="tag"] {
						color: @pine !important;
					}

					.ͼg,
					.ͼv,
					.ͼb,
					span.ͼg,
					span.ͼv,
					span.ͼb,
					span[class*="keyword"] {
						color: if(@flavor = dawn, @pine, @foam) !important;
					}

					.ͼl,
					.ͼ11,
					.ͼc,
					span.ͼl,
					span.ͼ11,
					span.ͼc,
					span[class*="function"],
					span[class*="type"],
					span[class*="class-name"],
					span[class*="primitive"] {
						color: @iris !important;
					}

					.ͼk,
					.ͼz,
					.ͼa,
					span.ͼk,
					span.ͼz,
					span.ͼa,
					span[class*="string"] {
						color: @rose !important;
					}

					.ͼj,
					.ͼy,
					.ͼ10,
					.ͼh,
					span.ͼj,
					span.ͼy,
					span.ͼ10,
					span.ͼh,
					span[class*="number"],
					span[class*="boolean"],
					span[class*="literal"] {
						color: @love !important;
					}

					.ͼm,
					.ͼ12,
					span.ͼm,
					span.ͼ12,
					span[class*="attribute"],
					span[class*="property"],
					span[class*="variable"],
					span[class*="operator"],
					span[class*="punctuation"] {
						color: @text !important;
					}

					.ͼ15,
					span.ͼ15,
					span[class*="escape"] {
						color: @subtle !important;
					}
				}
			}

			.btn-primary {
				background-color: @text;
				color: @base;
			}

			.btn-purple {
				color: @base;
				background-color: @accent-color;

				&:hover {
					background-color: lighten(@accent-color, 5%);
				}

				&:focus,
				&:active {
					background-color: darken(@accent-color, 5%);
				}
			}

			.btn-danger-outline {
				color: @love;
				border-color: @love;
			}

			.btn-ghost {
				&:not(:disabled) {
					&:hover {
						background-color: @overlay;
					}
				}
			}

			.bg-token-bg-primary {
				background-color: var(--bg-primary);
			}
			.bg-token-main-surface-primary {
				background-color: var(--main-surface-primary);
			}
			.bg-token-sidebar-surface {
				background-color: var(--sidebar-surface);
			}

			.__tailwind-utility(@color, @shade, @value) {
				.text-@{color}-@{shade},
				.dark\:text-@{color}-@{shade} {
					color: @value;
				}
				.bg-@{color}-@{shade},
				.dark\:bg-@{color}-@{shade} {
					background-color: @value;
				}
				.border-@{color}-@{shade} {
					border-color: @value;
				}
				.radix-state-checked\:bg-@{color}-@{shade}[data-state="checked"] {
					background-color: @value;
				}
			}

			.__tailwind-utility(green, 600, @pine);
			.__tailwind-utility(red, 500, @love);
			.__tailwind-utility(blue, 400, @accent-color);
			.__tailwind-utility(gray, 600, @highlightMed);
			.__tailwind-utility(gray, 500, @muted);

			.text-white {
				color: @base;
			}

			.bg-black {
				background-color: @surface;
			}
		}
	}

	/* Auth Rules */
	:root {
		@media (prefers-color-scheme: light) {
			#rose-pine-auth(@lightFlavor, @accentColor);
		}
		@media (prefers-color-scheme: dark) {
			#rose-pine-auth(@darkFlavor, @accentColor);
		}
	}

	#rose-pine-auth(@flavor, @accent) {
		@raw-base: @rose-pine[@@flavor][@base];
		@raw-surface: @rose-pine[@@flavor][@surface];

		@base: if(@flavor = dawn, @raw-surface, @raw-base);
		@surface: if(@flavor = dawn, @raw-base, @raw-surface);

		@overlay: @rose-pine[@@flavor][@overlay];
		@muted: @rose-pine[@@flavor][@muted];
		@subtle: @rose-pine[@@flavor][@subtle];
		@text: @rose-pine[@@flavor][@text];
		@love: @rose-pine[@@flavor][@love];
		@gold: @rose-pine[@@flavor][@gold];
		@rose: @rose-pine[@@flavor][@rose];
		@pine: @rose-pine[@@flavor][@pine];
		@foam: @rose-pine[@@flavor][@foam];
		@iris: @rose-pine[@@flavor][@iris];

		@accent-color: @rose-pine[@@flavor][@@accent];

		color: @text;

		background-color: @base;
		--main-page-background: @base;

		--text-primary: @text;
		--text-secondary: @subtle;
		--text-tertiary: @muted;
		--text-placeholder: @muted;

		--accent-blue: @accent-color;
		--link: @accent-color;

		--border-medium: @overlay;

		--button-primary-background: @text;
		--button-primary-hover: @subtle;
		--button-text-on-primary: @base;

		--button-outline-hover: @surface;

		--gray-100: @overlay;

		input {
			color: @text;
		}

		[class*="_toggleVisibilityButton"]:where(:hover, :focus-visible)::before {
			background-color: @surface;
		}

		[data-overlay-container] [class*="_tooltip"] {
			--tooltip-background-color: @surface !important;
			--tooltip-color: @text !important;
		}
	}
}

