/* ==UserStyle==
@name           Rosé Pine for NixOS Search
@description    Soho vibes for NixOS Search
@version        1.0.0
@license        MIT
@author         Jackson Trenerry (https://github.com/JTrenerry)
@namespace      https://github.com/rose-pine/
@homepageURL    https://github.com/rose-pine/userstyles
@updateURL      https://github.com/rose-pine/userstyles/raw/main/styles/nixos-search/rose-pine.user.less
@preprocessor   less

@var select lightVariant "Light Variant" ["dawn:Rosé Pine Dawn*", "moon:Rosé Pine Moon", "main:Rosé Pine"]
@var select darkVariant "Dark Variant" ["dawn:Rosé Pine Dawn", "moon:Rosé Pine Moon", "main:Rosé Pine"]
@var select accentColor "Accent" ["love:Love*", "gold:Gold", "rose:Rose", "pine:Pine", "foam:Foam", "iris:Iris"]
==/UserStyle== */

@-moz-document domain("search.nixos.org") {
	#rose-pine(@lookup, @accent) {
		@base: @rose-pine[@@lookup][@base];
		@surface: @rose-pine[@@lookup][@surface];
		@overlay: @rose-pine[@@lookup][@overlay];
		@muted: @rose-pine[@@lookup][@muted];
		@subtle: @rose-pine[@@lookup][@subtle];
		@text: @rose-pine[@@lookup][@text];
		@love: @rose-pine[@@lookup][@love];
		@gold: @rose-pine[@@lookup][@gold];
		@rose: @rose-pine[@@lookup][@rose];
		@pine: @rose-pine[@@lookup][@pine];
		@foam: @rose-pine[@@lookup][@foam];
		@iris: @rose-pine[@@lookup][@iris];
		@highlightLow: @rose-pine[@@lookup][@highlightLow];
		@highlightMed: @rose-pine[@@lookup][@highlightMed];
		@highlightHigh: @rose-pine[@@lookup][@highlightHigh];
		@accent-color: @rose-pine[@@lookup][@@accent];

		::selection {
			background-color: fade(@accent-color, 30%);
		}

		input,
		textarea {
			&::placeholder {
				color: @muted !important;
			}
		}

		--background-color: @base;
		--badge-background: @overlay;
		--button-active-background: @overlay;
		--button-active-hover-background: @overlay;
		--button-background: @surface;
		--button-hover-background: @overlay;
		--color-active-hover-tab: @surface;
		--color-active-tab: @base;
		--color-hover-tab: @surface;
		--headerbar-background-color: @overlay; //change
		--hover-background: @base;
		--link-color: @accent;
		--info-label-background: @overlay;
		--dark-blue: @accent;
		--light-blue: @accent;
		--line-color: @base;
		--search-result-short-details-color: @muted;
		--search-result-divider-line-color: @overlay;
		--search-result-title-color: @accent;
		--search-sidebar-link-color: @text;
		--search-sidebar-selected-link-background: @overlay;
		--search-sidebar-selected-link-color: @accent;
		--terminal-background: @overlay;
		--terminal-color: @accent;
		--text-color: @text;
		--text-color-light: @text;
		--text-color-warning: @love;

		.label,
		.badge {
			color: @text;
		}

		a:hover,
		a:focus {
			color: @text;
		}
	}

	:root {
		@media (prefers-color-scheme: light) {
			#rose-pine(@lightVariant, @accentColor);
		}
		@media (prefers-color-scheme: dark) {
			#rose-pine(@darkVariant, @accentColor);
		}
	}
}

